n_X = 5\text{ mol}, \quad n_Y = 10\text{ mol}, \quad n_{\text{total}} = 15\text{ mol}
\chi_X = \frac{5}{15} = \frac{1}{3}, \quad \chi_Y = \frac{10}{15} = \frac{2}{3}
